#include <stdio.h>

int main() {
    int a = 65;
    float b = 3.14;

    // Void Pointer can hold any type's address
    void *ptr;

    ptr = &a;
    // Must cast before dereferencing
    printf("int: %d\n", *(int *)ptr);

    ptr = &b;
    printf("float: %.2f\n", *(float *)ptr);

    return 0;
}
